package com.servicerca.service; import com.servicerca.dto.media.MediaUploadResponse;import com.servicerca.exception.BusinessException;import com.servicerca.model.*;import com.servicerca.repository.MediaFileRepository;import org.springframework.beans.factory.annotation.Value;import org.springframework.http.MediaType;import org.springframework.stereotype.Service;import org.springframework.web.multipart.MultipartFile;import software.amazon.awssdk.auth.credentials.*;import software.amazon.awssdk.regions.Region;import software.amazon.awssdk.services.s3.*;import software.amazon.awssdk.services.s3.model.*;import java.net.URI;import java.util.*;
@Service public class StorageService{private final S3Client s3;private final String bucket,endpoint;private final MediaFileRepository media;public StorageService(@Value("${app.storage.endpoint}")String endpoint,@Value("${app.storage.access-key}")String access,@Value("${app.storage.secret-key}")String secret,@Value("${app.storage.bucket}")String bucket,@Value("${app.storage.region}")String region,MediaFileRepository media){this.endpoint=endpoint;this.bucket=bucket;this.media=media;s3=S3Client.builder().endpointOverride(URI.create(endpoint)).region(Region.of(region)).credentialsProvider(StaticCredentialsProvider.create(AwsBasicCredentials.create(access,secret))).forcePathStyle(true).build();}public MediaUploadResponse upload(User owner,MultipartFile file){var allowed=Set.of(MediaType.IMAGE_JPEG_VALUE,MediaType.IMAGE_PNG_VALUE,"image/webp");if(file.isEmpty()||file.getSize()>8*1024*1024||!allowed.contains(file.getContentType()))throw new BusinessException("INVALID_FILE","La imagen debe ser JPG, PNG o WebP y pesar hasta 8 MB.");try{try{s3.headBucket(b->b.bucket(bucket));}catch(Exception e){s3.createBucket(b->b.bucket(bucket));}var key="users/"+owner.getId()+"/"+UUID.randomUUID();s3.putObject(PutObjectRequest.builder().bucket(bucket).key(key).contentType(file.getContentType()).build(),software.amazon.awssdk.core.sync.RequestBody.fromBytes(file.getBytes()));var m=media.save(MediaFile.builder().owner(owner).objectKey(key).contentType(file.getContentType()).sizeBytes(file.getSize()).build());return new MediaUploadResponse(m.getId(),endpoint+"/"+bucket+"/"+key,m.getContentType(),m.getSizeBytes());}catch(Exception e){throw new BusinessException("STORAGE_UNAVAILABLE","No se pudo guardar el archivo.");}}}
